    wRisk       = 0.25
    wConfidence = 0.15
    wActor      = 0.05
)

var prioritySeverityRanks = map[string]int{
    "none":     0,
    "low":      1,
    "medium":   2,
    "high":     3,
    "critical": 4,
}

type priorityComponents struct {
    Severity   float64 `json:"severity"`
    Recency    float64 `json:"recency"`
    Risk       float64 `json:"risk"`
    Confidence float64 `json:"confidence"`
    Actor      float64 `json:"actor"`
}

type prioritizeOutput struct {
    SourceIP          string           `json:"source_ip"`
    ThreatType        string           `json:"threat_type"`
    PriorityScore     float64          `json:"priority_score"`
    PriorityLabel     string           `json:"priority_label"`
    Components        priorityComponents `json:"components"`
    EnrichedRiskScore float64          `json:"enriched_risk_score"`
    IOCSeverity       string           `json:"ioc_severity"`
    ThreatActors      []string         `json:"threat_actors"`
    ReferenceTime     string           `json:"reference_time"`
}

func runPrioritize(args []string) int {
    fs := newFlagSet("prioritize")
    refStr := fs.String("reference-time", "", "reference timestamp for recency scoring (RFC3339)")
    if !parseFlags(fs, args) {
        return 1
    }
    if !isFlagSet(fs, "reference-time") || *refStr == "" {
        fmt.Fprintln(os.Stderr, "missing --reference-time flag")
        return 1
    }
    refTime, err := parseTime(*refStr)
    if err != nil {
        fmt.Fprintln(os.Stderr, err)
        return 1
    }

    scanner := bufio.NewScanner(os.Stdin)
    scanner.Buffer(make([]byte, 1024*1024), 16*1024*1024)

    var results []prioritizeOutput
    lineNo := 0
    for scanner.Scan() {
        lineNo++
        line := scanner.Text()
        if line == "" {
            continue
        }
        var threat map[string]interface{}
        if err := json.Unmarshal([]byte(line), &threat); err != nil {
            fmt.Fprintf(os.Stderr, "line %d: %v\n", lineNo, err)
            return 2
        }
        out, ok := prioritizeThreat(threat, refTime)
        if !ok {
            continue
        }
        results = append(results, out)
    }
    if err := scanner.Err(); err != nil {
        fmt.Fprintln(os.Stderr, err)
        return 1
    }

    sort.SliceStable(results, func(i, j int) bool {
        if results[i].PriorityScore != results[j].PriorityScore {
            return results[i].PriorityScore > results[j].PriorityScore
        }
        return results[i].SourceIP < results[j].SourceIP
    })

    writer := bufio.NewWriter(os.Stdout)
    defer writer.Flush()
    for _, r := range results {
        b, err := json.Marshal(r)
        if err != nil {
            fmt.Fprintf(os.Stderr, "failed to encode output: %v\n", err)
            return 1
        }
        fmt.Fprintln(writer, string(b))
    }
    return 0
}

func prioritizeThreat(threat map[string]interface{}, refTime time.Time) (prioritizeOutput, bool) {
    sourceIP := getStringDefault(threat, "source_ip")
    threatType := getStringDefault(threat, "threat_type")

    eventTime := threatReferenceTime(threat)
    refStr := ""
    if !eventTime.IsZero() {
        refStr = eventTime.UTC().Format(time.RFC3339)
    }

    ageMinutes := 0.0
    if !eventTime.IsZero() {
        ageMinutes = refTime.Sub(eventTime).Minutes()
    }
    if ageMinutes < 0 {
        ageMinutes = 0
    }
    recency := math.Pow(2, -ageMinutes/60.0)

    riskScore, _ := getFloat(threat, "enriched_risk_score")
    risk := riskScore / 500.0
    if risk > 1.0 {
        risk = 1.0
    }
    if risk < 0 {
        risk = 0
    }

    confidence := 0.0
    if c, ok := getFloat(threat, "max_ioc_confidence"); ok {
        confidence = c
    }
    if confidence < 0 {
        confidence = 0
    }
    if confidence > 1 {
        confidence = 1
    }

    actors := []string{}
    if a, ok := getStringSlice(threat, "threat_actors"); ok {
        actors = a
    }
    actor := float64(len(actors)) / 3.0
    if actor > 1.0 {
        actor = 1.0
    }
    if actor < 0 {
        actor = 0
    }

    severity := getStringDefault(threat, "ioc_severity")
    severityRank := prioritySeverityRanks[severity]
    severityComponent := float64(severityRank) / 4.0

    score := wSeverity*severityComponent +
        wRecency*recency +
        wRisk*risk +
        wConfidence*confidence +
        wActor*actor

    label := priorityLabel(score)

    return prioritizeOutput{
        SourceIP:          sourceIP,
        ThreatType:        threatType,
        PriorityScore:     round4(score),
        PriorityLabel:     label,
        Components: priorityComponents{
            Severity:   round4(severityComponent),
            Recency:    round4(recency),
            Risk:       round4(risk),
            Confidence: round4(confidence),
            Actor:      round4(actor),
        },
        EnrichedRiskScore: riskScore,
        IOCSeverity:       severity,
        ThreatActors:      actors,
        ReferenceTime:     refStr,
    }, true
}

func priorityLabel(score float64) string {
    switch {
    case score >= 0.75:
        return "critical"
    case score >= 0.50:
        return "high"
    case score >= 0.25:
        return "medium"
    default:
        return "low"
    }
}

func round4(f float64) float64 {
    return math.Round(f*10000) / 10000
}
