func prioritizeThreat(threat map[string]interface{}, refTime time.Time) (prioritizeOutput, bool) {
    sourceIP := getStringDefault(threat, "source_ip")
    threatType := getStringDefault(threat, "threat_type")

    eventTime := threatReferenceTime(threat)
    refStr := ""
    if tt, ok := getString(threat, "threat_type"); ok && tt == "privilege_escalation" {
        if ts, ok := getString(threat, "timestamp"); ok {
            refStr = ts
        }
    } else {
        if ts, ok := getString(threat, "first_seen"); ok {
            refStr = ts
        }
    }

    ageMinutes := 0.0
    if !eventTime.IsZero() {
        ageMinutes = refTime.Sub(eventTime).Minutes()
    }
    if ageMinutes < 0 {
        ageMinutes = 0
    }
    recency := math.Pow(2, -ageMinutes/60.0)

    riskScore, _ := getFloat(threat, "enriched_risk_score")
    risk := riskScore / 500.0
    if risk > 1.0 {
        risk = 1.0
    }
    if risk < 0 {
        risk = 0
    }

    confidence := 0.0
    if c, ok := getFloat(threat, "max_ioc_confidence"); ok {
        confidence = c
    }
    if confidence < 0 {
        confidence = 0
    }
    if confidence > 1 {
        confidence = 1
    }

    actors := []string{}
    if a, ok := getStringSlice(threat, "threat_actors"); ok {
        actors = a
    }
    actor := float64(len(actors)) / 3.0
    if actor > 1.0 {
        actor = 1.0
    }
    if actor < 0 {
        actor = 0
    }

    severity := getStringDefault(threat, "ioc_severity")
    severityRank := prioritySeverityRanks[severity]
    severityComponent := float64(severityRank) / 4.0

    score := wSeverity*severityComponent +
        wRecency*recency +
        wRisk*risk +
        wConfidence*confidence +
        wActor*actor

    label := priorityLabel(score)

    return prioritizeOutput{
        SourceIP:      sourceIP,
        ThreatType:    threatType,
        PriorityScore: round4(score),
        PriorityLabel: label,
        Components: priorityComponents{
            Severity:   round4(severityComponent),
            Recency:    round4(recency),
            Risk:       round4(risk),
            Confidence: round4(confidence),
            Actor:      round4(actor),
        },
        EnrichedRiskScore: riskScore,
        IOCSeverity:       severity,
        ThreatActors:      actors,
        ReferenceTime:     refStr,
    }, true
}

func priorityLabel(score float64) string {
    switch {
    case score >= 0.75:
        return "critical"
    case score >= 0.50:
        return "high"
    case score >= 0.25:
        return "medium"
    default:
        return "low"
    }
}

func round4(f float64) float64 {
    return math.Round(f*10000) / 10000
}
